UPDATE `achievement` SET `name_2` = '자원 봉사', `name_3` = 'Sur la base du volontariat', `name_4` = 'Freiwillige Arbeit', `name_5` = '志愿工作', `name_6` = '志願工作者', `name_7` = 'Trabajo de voluntario', `name_8` = 'Trabajo de voluntario', `name_9` = 'Работа для добровольцев', `description_2` = '안카헤트에서 황혼의 지원병을 죽이지 않고 어둠추적자 제도가 처치 (영웅)', `description_3` = 'Vaincre Jedoga Cherchelombre à Ahn\'kahet sans tuer de volontaires du crépuscule en mode héroïque.', `description_4` = 'Bezwingt Jedoga Schattensucher in Ahn\'kahet auf dem Schwierigkeitsgrad \'Heroisch\', ohne dabei Freiwillige des Schattenhammers umzubringen.', `description_5` = '在不杀死任何暮光志愿者的情况下，击败安卡赫特的耶戈达·觅影者（英雄难度）。', `description_6` = '英雄模式中，在不擊殺任何擊敗暮光志願者的情況下擊敗安卡罕特的潔杜佳·尋影者。', `description_7` = 'Derrota a Jedoga Buscasombras en Ahn\'kahet en dificultad heroica sin matar a ninguno de los Voluntarios Crepusculares.', `description_8` = 'Derrota a Jedoga Buscasombras en Ahn\'kahet en dificultad heroica sin matar a ninguno de los Voluntarios Crepusculares.', `description_9` = 'Убейте Джедогу Искательницу Теней в Ан\'Кахете в героическом режиме, не убивая добровольцев культа Сумеречного Молота.' WHERE `id` = 2056;
UPDATE `achievement` SET `name_2` = '아놔! 노보스!', `name_3` = 'Novos l\'Invocateur', `name_4` = 'Oh Novos!', `name_5` = '哦，诺沃斯！', `name_6` = '喔!被孤立的諾沃司', `name_7` = 'Oh, ¡Novos!', `name_8` = 'Oh, ¡Novos!', `name_9` = 'Снова Новос!', `description_2` = '드락타론 성채에서 언데드 수하가 도착하기 전에 소환사 노보스 처치 (영웅)', `description_3` = 'Vaincre Novos l\'Invocateur dans le donjon de Drak\'Tharon sans que des sbires morts-vivants atteignent le sol en mode héroïque.', `description_4` = 'Bezwingt Novos den Beschwörer in der Feste Drak\'Tharon auf dem Schwierigkeitsgrad \'Heroisch\', ohne dass untote Diener den Boden erreichen dürfen.', `description_5` = '在没有任何亡灵爪牙爬上地面的情况下击败达克萨隆要塞的召唤者诺沃斯（英雄难度）。', `description_6` = '英雄模式中，在不讓任何不死爪牙抵達樓下的情況下擊敗德拉克薩隆要塞的『召喚者』諾沃司。', `description_7` = 'Derrota a Novos el Invocador en la Fortaleza de Drak\'Tharon en dificultad heroica sin dejar que ningún esbirro no-muerto llegue al suelo.', `description_8` = 'Derrota a Novos el Invocador en la Fortaleza de Drak\'Tharon en dificultad heroica sin dejar que ningún esbirro no-muerto llegue al suelo.', `description_9` = 'Убейте Новоса Призывателя в крепости Драк\'Тарон в героическом режиме, не дав его прислужникам спуститься с лестницы.' WHERE `id` = 2057;
