UPDATE `achievement` SET `name_2` = '공허의 춤', `name_3` = 'La danse du vide', `name_4` = 'Wie auf rohen Eiern', `name_5` = '虚空之舞', `name_6` = '虛無之舞', `name_7` = 'Un baile con el vacío', `name_8` = 'Un baile con el vacío', `name_9` = 'Танец пустоты', `description_2` = '보랏빛 요새에서 공허의 보초병을 죽이지 않고 파멸자 주라마트 처치 (영웅)', `description_3` = 'Vaincre Zuramat l\'Oblitérateur dans le fort Pourpre sans tuer de factionnaire du Vide en mode héroïque.', `description_4` = 'Bezwingt Zuramat den Vernichter in der Violetten Festung auf dem Schwierigkeitsgrad \'Heroisch\', ohne dabei eine einzige Leerenwache umzubringen.', `description_5` = '在不杀死任何虚空斥候的情况下，击败紫罗兰监狱中的湮灭者祖拉玛特（英雄难度）。', `description_6` = '英雄模式中，在未擊殺任何虛無哨兵的情況下擊敗紫羅蘭堡中的『消滅者』舒拉邁特。', `description_7` = 'Derrota a Zuramat el Obliterador en El Bastión Violeta en dificultad heroica sin matar a ningún centinela del vacío.', `description_8` = 'Derrota a Zuramat el Obliterador en El Bastión Violeta en dificultad heroica sin matar a ningún centinela del vacío.', `description_9` = 'Одержите победу над Зураматом Уничтожителем в Аметистовой крепости в героическом режиме, не убив ни одного караульного Бездны.' WHERE `id` = 2153;
UPDATE `achievement` SET `name_2` = '브란을 보호하라!', `name_3` = 'Au nez et à la barbe de Brann', `name_4` = 'Der ist noch so gut wie Neu', `name_5` = '毫发无伤的布莱恩', `name_6` = '毫髮無傷的布萊恩', `name_7` = 'Brann totalmente nuevo', `name_8` = 'Brann totalmente nuevo', `name_9` = 'Поле Бранни', `description_2` = '돌의 전당에서 브란 브론즈비어드가 전혀 피해를 입지 않은 상태로 시대의 심판장에 나타나는 적들 처치 (영웅)', `description_3` = 'Vaincre les ennemis du tribunal des Âges dans les salles de Pierre sans que Brann Barbe-de-bronze subisse des dégâts en mode héroïque.', `description_4` = 'Gewinnt das Gefecht \'Tribunal der Zeitalter\' in den Hallen des Steins auf dem Schwierigkeitsgrad \'Heroisch\', ohne dass Brann Bronzebart Schaden erleiden darf.', `description_5` = '在岩石大厅的远古法庭事件中获胜，并且保证布莱恩·铜须不受到任何伤害（英雄难度）。', `description_6` = '英雄模式中，在布萊恩·銅鬚未受到任何傷害的情況下完成石之大廳裡的歲月議庭戰役。', `description_7` = 'Derrota el encuentro del Tribunal de los Tiempos en las Cámaras de Piedra en dificultad heroica sin permitir que Brann Barbabronce sufra daño.', `description_8` = 'Derrota el encuentro del Tribunal de los Tiempos en las Cámaras de Piedra en dificultad heroica sin permitir que Brann Barbabronce sufra daño.', `description_9` = 'Одержите верх над Трибуналом Веков в Чертогах Камня в героическом режиме, чтобы Бранн Бронзобород не получил ни одного повреждения.' WHERE `id` = 2154;
