UPDATE `achievement` SET `name_2` = '놈리건 작전', `name_3` = 'Opération Gnomeregan', `name_4` = 'Operation: Gnomeregan', `name_5` = '诺莫瑞根行动', `name_6` = '行動:諾姆瑞根', `name_7` = 'Operación: Gnomeregan', `name_8` = 'Operación: Gnomeregan', `name_9` = 'Операция ""Гномреган""', `description_2` = '땜장이왕 멕카토크와 놈리건 피난민들을 도와 놈리건 외부 되찾기', `description_3` = 'Avoir aidé le Grand Bricoleur Mekkanivelle et les exilés de Gnomeregan à reprendre la surface de Gnomeregan.', `description_4` = 'Ihr habt Hochtüftler Mekkadrill und den Verbannten von Gnomeregan bei der Rückeroberung der Oberfläche von Gnomeregan geholfen.', `description_5` = '在光复诺莫瑞根地上部分中协助过大工匠梅卡托克和诺莫瑞根流亡者。', `description_6` = '你協助了大工匠梅卡托克和諾姆瑞根流亡者奪回諾姆瑞根的地表層。', `description_7` = 'Ayudaste al Manitas Mayor Mekkatorque y a los Exiliados de Gnomeregan a que recuperaran la superficie de Gnomeregan.', `description_8` = 'Ayudaste al Manitas Mayor Mekkatorque y a los Exiliados de Gnomeregan a que recuperaran la superficie de Gnomeregan.', `description_9` = 'Вы помогли главному механику Меггакруту и изгнанникам Гномрегана восстановить контроль над поверхностью Гномрегана.' WHERE `id` = 4786;
